INSERT INTO "CommunityPolicy" ("Id","TenantId","MemberPosting","PublicAllowed","BlockingAllowed","PostStages","EventStages","Revision") SELECT gen_random_uuid(),tenant,true,false,true,'[]','[]',0 FROM community_seed;
INSERT INTO "ActivityCategory" ("Id","TenantId","Name","Kind","Active") SELECT activity,tenant,'Synthetic Service','Activity',true FROM community_seed UNION ALL SELECT eventtype,tenant,'Synthetic Meeting','Event',true FROM community_seed;
INSERT INTO "Units" ("Id","TenantId","ParentId","LevelId","Name","Code","Status","Details","CreatedAt","UpdatedAt","Revision") SELECT gen_random_uuid(),c.tenant,u."ParentId",u."LevelId",'Synthetic extra chapter '||i,'CB'||i,'Active','{}',now(),now(),0 FROM generate_series(11,10000) i CROSS JOIN community_seed c JOIN "Units" u ON u."Id"=(SELECT id FROM bench_chapters LIMIT 1);
INSERT INTO "ActivityPost" ("Id","TenantId","AuthorId","UnitId","CommitteeId","Official","CategoryId","EventId","Title","Body","Location","Tags","Mentions","Audience","Visibility","Status","Stages","Stage","Revision","Featured","Achievement","CreatedAt","ScheduledAt","PublishedAt") SELECT id,tenant,actor,chapter,NULL,true,activity,NULL,'Synthetic chapter story '||i,'<p>Measured synthetic service activity.</p>','',ARRAY[]::text[],ARRAY[]::uuid[],ARRAY[chapter],'Chapter','Published','[]',0,0,false,false,now()-i*interval '1 minute',NULL,now()-i*interval '1 minute' FROM community_posts;
INSERT INTO "CommunityEvent" ("Id","TenantId","AuthorId","UnitId","CategoryId","CoHosts","Title","Body","Venue","Mode","OnlineUrl","TimeZone","StartsAt","EndsAt","RegistrationOpens","RegistrationCloses","ScheduledAt","PublishedAt","Visibility","Audience","MemberIds","CategoryIds","CommitteeIds","LeadersOnly","InvitationOnly","AllowGuests","MaxCompanions","RegistrationApproval","Capacity","Questions","Status","Stages","Stage","Revision","CreatedAt") SELECT id,tenant,actor,chapter,eventtype,ARRAY[]::uuid[],'Synthetic event '||i,'Synthetic benchmark program','Test venue','In Person',NULL,'Asia/Kolkata',now()+((i%60)-30)*interval '1 day',now()+((i%60)-30)*interval '1 day'+interval '2 hours',now()-interval '90 days',now()+interval '90 days',NULL,now()-interval '1 day','Chapter',ARRAY[chapter],ARRAY[]::uuid[],ARRAY[]::uuid[],ARRAY[]::uuid[],false,false,false,0,false,1000,'[]','Published','[]',0,0,now() FROM community_events;
INSERT INTO "AspNetUsers" ("Id","FullName","PlatformAdmin","UserName","NormalizedUserName","Email","NormalizedEmail","EmailConfirmed","PhoneNumberConfirmed","TwoFactorEnabled","LockoutEnabled","AccessFailedCount") SELECT id,'Synthetic attendee '||i,false,'synthetic-'||id,upper('synthetic-'||id),id||'@example.test',upper(id||'@example.test'),true,false,false,false,0 FROM community_users;
INSERT INTO "EventRegistration" ("Id","TenantId","EventId","UserId","MembershipId","Name","Status","Companions","Answers","At","Revision") SELECT id,tenant,event,usr,NULL,'Synthetic participant','Confirmed',0,'{}',now(),0 FROM community_registrations;
INSERT INTO "EventAttendance" ("Id","TenantId","EventId","RegistrationId","OperatorId","At","EntryPoint","Voided","Correction","PeopleCount") SELECT gen_random_uuid(),r.tenant,r.event,r.id,c.actor,now(),'Synthetic benchmark entrance',false,'',1 FROM community_registrations r CROSS JOIN community_seed c WHERE r.i%2=0;
INSERT INTO "EventInvitation" ("Id","TenantId","EventId","SenderId","UserId","MembershipId","Email","Name","TokenHash","Status","At","ExpiresAt","RespondedAt") SELECT gen_random_uuid(),r.tenant,r.event,c.actor,r.usr,NULL,r.usr||'@example.test','Synthetic invitee',md5(r.id::text),'In App',now(),now()+interval '7 days',NULL FROM community_registrations r CROSS JOIN community_seed c;
INSERT INTO "ActivityReaction" ("Id","TenantId","PostId","UserId","Kind") SELECT gen_random_uuid(),p.tenant,p.id,c.actor,'Appreciate' FROM community_posts p CROSS JOIN community_seed c WHERE p.i%2=0;
