-- Synthetic fixtures only. Called in an isolated benchmark database or rollback transaction.
CREATE TEMP TABLE community_seed AS SELECT tenant,(SELECT "Id" FROM "AspNetUsers" ORDER BY "Id" LIMIT 1) actor,gen_random_uuid() activity,gen_random_uuid() eventtype FROM bench_chapters LIMIT 1;
CREATE TEMP TABLE community_posts AS SELECT n AS i,gen_random_uuid() id,c.tenant,c.actor,c.activity,(SELECT id FROM bench_chapters WHERE bench_chapters.i=((n-1)%10)+1) chapter FROM generate_series(1,100000) n CROSS JOIN community_seed c;
CREATE TEMP TABLE community_events AS SELECT n AS i,gen_random_uuid() id,c.tenant,c.actor,c.eventtype,(SELECT id FROM bench_chapters WHERE bench_chapters.i=((n-1)%10)+1) chapter FROM generate_series(1,10000) n CROSS JOIN community_seed c;
CREATE TEMP TABLE community_users AS SELECT i,gen_random_uuid() id FROM generate_series(1,100) i;
CREATE TEMP TABLE community_registrations AS SELECT n AS i,gen_random_uuid() id,c.tenant,(SELECT id FROM community_events WHERE community_events.i=((n-1)%1000)+1) event,(SELECT id FROM community_users WHERE community_users.i=((n-1)/1000)+1) usr FROM generate_series(1,50000) n CROSS JOIN community_seed c;
ANALYZE "ActivityPost"; ANALYZE "CommunityEvent"; ANALYZE "EventRegistration"; ANALYZE "EventAttendance"; ANALYZE "EventInvitation"; ANALYZE "ActivityReaction";
